<?php $mode = $mode ?? 'create'; $product = $product ?? []; $title = $mode === 'edit' ? 'Edit Item' : 'Add Inventory Item'; $itemTypes = $itemTypes ?? \Product::itemTypes(); $category = (string)($product['item_category'] ?? 'Tracker'); $needsIdentifier = in_array($category, ['Tracker', 'FLS', 'Cameras'], true); ?>
<div class="row justify-content-center"><div class="col-lg-8"><div class="card shadow-sm border-0"><div class="card-body p-3 p-lg-4">
<h2 class="h4 mb-1"><?= htmlspecialchars($title) ?></h2><p class="text-secondary small mb-4">Serialized equipment is tracked by its unique identifier and installed directly from inventory.</p>
<?php if (!empty($error)): ?><div class="alert alert-danger"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
<form method="post" class="row g-3"><?= $this->csrfField() ?>
<div class="col-md-6"><label class="form-label" for="item-category">Category</label><select class="form-select" name="item_category" id="item-category" required><?php foreach ($itemTypes as $optionCategory => $types): ?><option value="<?= htmlspecialchars($optionCategory) ?>" <?= $category === $optionCategory ? 'selected' : '' ?>><?= htmlspecialchars($optionCategory === 'Sim cards' ? 'SIM cards / Lines' : $optionCategory) ?></option><?php endforeach; ?></select></div>
<div class="col-md-6"><label class="form-label" for="item-type">Type</label><select class="form-select" name="item_type" id="item-type" required></select></div>
<div class="col-md-6"><label class="form-label" id="identifier-label" for="item-identifier">Serial number / IMEI (digits only) <?= $needsIdentifier ? '<span class="text-danger">*</span>' : '<span class="text-secondary fw-normal">(optional)</span>' ?></label><input class="form-control" id="item-identifier" name="identifier" inputmode="numeric" pattern="[0-9]*" value="<?= htmlspecialchars((string)($product['identifier'] ?? $product['imei'] ?? ''), ENT_QUOTES, 'UTF-8') ?>" <?= $needsIdentifier ? 'required' : '' ?>><div class="form-text" id="identifier-help"><?= $needsIdentifier ? 'Required for tracker IMEI and FLS / camera serials used during installation.' : 'Optional; enter digits only when this item has a unique SIM number.' ?></div></div>
<div class="col-md-6"><label class="form-label" for="item-quantity">Quantity</label><input class="form-control" id="item-quantity" type="number" min="<?= $needsIdentifier && $mode === 'edit' ? '0' : '1' ?>" <?= $needsIdentifier ? 'max="1"' : '' ?> name="quantity" value="<?= (int)($product['quantity'] ?? 1) ?>" required><div class="form-text" id="quantity-help"><?= $needsIdentifier ? 'Unique serial numbers are tracked one physical unit per inventory row.' : 'Total units in this stock line.' ?></div></div>
<div class="col-md-6"><label class="form-label" for="cost-price">Cost price</label><input class="form-control" id="cost-price" type="number" step="0.01" min="0" name="cost_price" value="<?= htmlspecialchars((string)($product['cost_price'] ?? 0), ENT_QUOTES, 'UTF-8') ?>"></div>
<div class="col-md-6"><label class="form-label" for="selling-price">Selling price</label><input class="form-control" id="selling-price" type="number" step="0.01" min="0" name="selling_price" value="<?= htmlspecialchars((string)($product['selling_price'] ?? 0), ENT_QUOTES, 'UTF-8') ?>"></div>
<div class="col-12"><button class="btn btn-primary" type="submit">Save item</button> <a class="btn btn-outline-secondary" href="/index.php?controller=inventory">Back to inventory</a></div></form>
</div></div></div></div>
<script>
const inventoryTypes=<?= json_encode($itemTypes, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>,categorySelect=document.getElementById('item-category'),typeSelect=document.getElementById('item-type'),identifierInput=document.getElementById('item-identifier'),quantityInput=document.getElementById('item-quantity'),isEdit=<?= $mode === 'edit' ? 'true' : 'false' ?>;let preferredType=<?= json_encode($product['item_type'] ?? '') ?>;
function syncInventoryCategory(changed=false){const tracked=['Tracker','FLS','Cameras'].includes(categorySelect.value);identifierInput.required=tracked;quantityInput.max=tracked?'1':'';quantityInput.min=tracked&&isEdit?'0':'1';document.getElementById('identifier-label').innerHTML='Serial number / IMEI (digits only) '+(tracked?'<span class="text-danger">*</span>':'<span class="text-secondary fw-normal">(optional)</span>');document.getElementById('identifier-help').textContent=tracked?'Required for tracker IMEI and FLS / camera serials used during installation.':'Optional; enter digits only when this item has a unique SIM number.';document.getElementById('quantity-help').textContent=tracked?'Unique serial numbers are tracked one physical unit per inventory row.':'Total units in this stock line.';if(changed&&tracked)quantityInput.value='1';if(tracked&&Number(quantityInput.value)>1)quantityInput.value='1';typeSelect.innerHTML='';(inventoryTypes[categorySelect.value]||[]).forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;option.selected=value===preferredType;typeSelect.append(option);});preferredType='';}
categorySelect.addEventListener('change',()=>syncInventoryCategory(true));syncInventoryCategory();
</script>
